mapper.select:
select c.contact_info_id, c.bp_id, c.email, c.phone, c.fax, c.position, (select sc.meaning value_name from sys_code_value_b_v sc where sc.code = 'FND.BP_POSITION' and sc.code_value = c.position) position_n, c.is_sign_person, c.contact_person, c.contact_person||c.cell_phone contact_info, c.cell_phone, c.address_id, a.country||a.province||a.city ||a.district||a.address contact_address, c.enabled_flag, c.emergency_contact from hls_bp_master_contact_info c left join ( select ma.address_id, ma.country, (select fp.description from fnd_province fp where fp.province = ma.province) province, (select fc.description from fnd_city fc where fc.city = ma.city) city, (select fd.description from fnd_district fd where fd.district = ma.district) district, ma.address from hls_bp_master_address ma ) a on c.address_id=a.address_id where c.bp_id = #{bpId}
and c.position =#{position}
and c.contact_person like concat('%',concat(#{contactPerson},'%'))
and c.CELL_PHONE like concat('%',concat(#{cellPhone},'%'))
